/* ══════════════════════════════════════════════
   判例○×

   憲法の択一は、ほぼ毎年が判例問題。本試験の5肢択一は「妥当でないものはどれか」
   という形で、1問に3〜5件の判例が入る（令和6年問5は5肢のうち3つが旭川学力テスト
   事件の別々の判示部分だった）。つまり5肢択一は、独立した○×判断が5つ並んだもの。

   そこで、いきなり5肢を組まず、まず「判例＋1つの主張＋○×」を積む。
   ・検証が1件ずつで済む（5つまとめて確かめるより確実）
   ・採点が厳密。○か×かなので、取りこぼしも過剰採点も起きない
   ・同じ判例・同じテーマの○×を5つ集めれば、そのまま5肢択一になる

   ── claim は判決文型、plain は平易型 ──
   憲法の択一は、判決文そのものの硬い言い回しが難易度の相当部分を占める。
   本試験の肢を実測すると平均101字（令和6年問6・令和7年問4の10肢）で、
   「法秩序全体の精神に照らし社会観念上是認できない態様」のように判決文の語彙が
   そのまま使われる。平易に書き直すと、読解の負荷が丸ごと抜け落ちてしまう。

   そこで claim に判決文の語彙と構文に寄せた肢（80字以上）を、plain に
   かみ砕いた言い回しを持たせ、出題オプションで切り替える。既定は判決文型。
   どちらで解いたかで正答率が変わるので、記録にもモードを残して別々に数える。

   判決文それ自体は著作権法13条3号により権利の目的とならないので、判旨の語を
   用いてよい。もっとも本試験の肢も原文の完全な引用ではなく判旨を圧縮した形なので、
   ここでも同様に圧縮する。資格学校のテキストの解説や事案の記述は別で、
   そちらは要約して自分の言葉で書く。

   ── 空欄にしてよいのは、本文と教義の知識だけで埋まる語 ──
   第一審や控訴審の結論のように、本文からは導けない外部の事実を空欄にしてはいけない。
   本試験の多肢選択は、本文と判例の理解だけで埋まるように作られている。
   愛媛玉串料の可部反対意見で「第一審は違憲とし」の違憲を空欄にして踏んだ。

   ── ok は「その主張が判例に照らして正しいか」──
   誤りの主張には、どこがどう違うのかを why に書く。「×」とだけ言われても、
   何が違うのか分からなければ学習にならない。

   ── 出典は必ず添える ──
   判例名と裁判年月日を cite に置く。あとから原典に当たれるようにするため。
   ══════════════════════════════════════════════ */

